def feature(text: str) -> float:
    "Ratio of phrases differing by one word in adjacent sentences"
    sentences = list(re.split(r'[.!?]+', text))
    count = sum(1 for i in range(1, len(sentences)) if len(set(sentences[i].split()).intersection(sentences[i-1].split())) == len(sentences[i].split()) - 1)
    return float(count) / (len(sentences) - 1) if len(sentences) > 1 else 0.0

